-- New homepage curation and three editorial articles. Apply once after 011.
-- Only explicitly requested about text is replaced; cookie wording is patched in place.
BEGIN;
UPDATE public.content SET body=body||'{"tr": "Bir motosikleti veya aracı kişisel kılan şey, detaylara gösterilen özen. KUZMIN’de karbonun dokusunu, parçanın çizgisini ve kullanım amacını birlikte düşünürüz.\nHazır bir parça ararken de aklındaki fikri geliştirirken de başlangıç noktamız aynı: aracı, parçayı ve beklentini anlamak. Malzeme, yüzey, ölçü ve uyumluluk bilgilerini açıkça paylaşarak karar vermeni kolaylaştırmayı amaçlarız.\nAradığın parçayı bulamadığında birkaç fotoğraf, temel ölçüler ve kısa bir açıklamayla talep oluşturabilirsin. Parçanın yapısı ve istediğin sonuç üzerinden üretim veya uygulama yöntemi değerlendirilir; kapsam ve teklif birlikte netleşir.\nSade bir görünüm, doğru uyumluluk ve açık iletişim. KUZMIN’in yaklaşımı, senin parçanı ve beklentini merkeze alır."}'::jsonb WHERE key='about';
UPDATE public.content SET body=jsonb_set(body,'{tr}',to_jsonb(replace(replace(body->>'tr','Çerez tercih kaydı bu tarayıcıda 180 gün tutulur; süresi dolduğunda yeniden seçim istenir.','Çerez bildirimi siteye her yeni girişte ve sayfa yenilendiğinde yeniden açılır. Önceki kabul bu ziyaret için otomatik izin sayılmaz; gerekli olmayan analiz yeni seçim yapılana kadar kapalıdır. Son tercih kaydı senkronizasyon amacıyla bu tarayıcıda en fazla 180 gün tutulabilir.'),'İsteğe bağlı analiz ilk ziyarette kapalıdır.','İsteğe bağlı analiz her yeni ziyarette başlangıçta kapalıdır.'))) WHERE key='privacy';
INSERT INTO public.content (id,key,title,body) VALUES ('journal-carbon-fiber','blog-karbon-fiber-nedir','{"tr": "Karbon Fiber Nedir? Hafifliğin Anatomisi", "en": "Karbon Fiber Nedir? Hafifliğin Anatomisi", "ru": "Karbon Fiber Nedir? Hafifliğin Anatomisi"}'::jsonb,'{"tr": "Karbon fiber, çok ince karbon liflerinden oluşan bir takviye malzemesidir. Bir motosiklet veya otomobil parçasında gördüğümüz “karbon” çoğu zaman bu liflerin reçineyle bir araya geldiği kompozit yapıdır. Lifler yük taşımaya katkı sağlarken reçine lifleri bir arada tutar ve yükün aktarılmasına yardımcı olur.\n## Motosiklet ve araçlarda neden kullanılır?\nKarbon kompozitler, uygun tasarım ve üretimle düşük ağırlıkta yüksek rijitlik hedeflenen parçalarda tercih edilebilir. Grenaj, çamurluk ve kaplama parçalarında biçim verme esnekliği ile belirgin doku da seçim nedenidir. Ancak her karbon parça, değiştirdiği parçadan mutlaka daha hafif veya daha dayanıklı değildir. Kalınlık, reçine miktarı, katman düzeni ve bağlantı detayları sonucu değiştirir.\n## Lif yönü neden önemlidir?\nKompozit parçanın davranışı liflerin yönüne bağlıdır. Bir yönde iyi sonuç veren katman düzeni, başka yöndeki yük için aynı sonucu vermeyebilir. Bu yüzden görünür örgü deseni, parçanın bütün teknik yapısını açıklamaz. Özellikle taşıyıcı veya güvenlikle ilgili parçalarda malzeme adı tek başına yeterli bir doğrulama değildir.\n## Karbon görünümlü kaplama ile karbon parça aynı mı?\nHayır. Karbon desenli film görsel bir kaplamadır; karbon lifli kompozitle aynı yapı değildir. Gerçek karbon kumaşının mevcut parça üzerine uygulanması da bağımsız bir kompozit parçayla aynı şey değildir. Ana parçanın korunduğu uygulamada toplam ağırlık azalacağı varsayılmamalıdır. Karbon/cam elyaf hibritlerde ise farklı takviyeler birlikte bulunur. Ürün açıklamasında yapının hangisi olduğu açıkça belirtilmelidir.\n## Satın almadan önce neye bakmalı?\nUyumluluk, malzeme bileşimi, bağlantı noktaları, yüzey ve montaj kapsamını birlikte incele. Ağırlık önemliyse karşılaştırılabilir koşullarda ölçülmüş ürün verisini iste. Doğrulanmamış genel yüzdeler yerine satın alacağın parçaya ait bilgiye dayan. Kullanım ve bakımda üreticinin ürün özelindeki talimatını izle; yüzey koruması, UV dayanımı veya ısı dayanımı bütün karbon parçalar için aynı kabul edilemez.\n### Karbon fiber her darbeye dayanır mı?\nHayır. Tasarımına ve darbenin biçimine göre hasar görebilir. Görünür yüzeyin sağlam olması iç yapıda hasar bulunmadığını tek başına kanıtlamaz. Şüpheli bir darbe sonrasında özellikle güvenlikle ilgili parçalarda uzman değerlendirmesi gerekir.\n### Parlak veya mat yüzey dayanımı belirler mi?\nParlak ve mat, yüzey tercihidir. Lif türü, katman düzeni ve üretim kalitesi hakkında tek başına kesin bir sonuç vermez.\n## Kendi parçan için nereden başlamalısın?\nAracının bilgilerini, parçanın farklı açılardan fotoğraflarını ve temel ölçülerini hazırlamak doğru bir başlangıçtır. Malzeme ve yöntem, görünüm hedefinin yanında parçanın görevine göre değerlendirilmelidir.", "en": "Karbon fiber, çok ince karbon liflerinden oluşan bir takviye malzemesidir. Bir motosiklet veya otomobil parçasında gördüğümüz “karbon” çoğu zaman bu liflerin reçineyle bir araya geldiği kompozit yapıdır. Lifler yük taşımaya katkı sağlarken reçine lifleri bir arada tutar ve yükün aktarılmasına yardımcı olur.\n## Motosiklet ve araçlarda neden kullanılır?\nKarbon kompozitler, uygun tasarım ve üretimle düşük ağırlıkta yüksek rijitlik hedeflenen parçalarda tercih edilebilir. Grenaj, çamurluk ve kaplama parçalarında biçim verme esnekliği ile belirgin doku da seçim nedenidir. Ancak her karbon parça, değiştirdiği parçadan mutlaka daha hafif veya daha dayanıklı değildir. Kalınlık, reçine miktarı, katman düzeni ve bağlantı detayları sonucu değiştirir.\n## Lif yönü neden önemlidir?\nKompozit parçanın davranışı liflerin yönüne bağlıdır. Bir yönde iyi sonuç veren katman düzeni, başka yöndeki yük için aynı sonucu vermeyebilir. Bu yüzden görünür örgü deseni, parçanın bütün teknik yapısını açıklamaz. Özellikle taşıyıcı veya güvenlikle ilgili parçalarda malzeme adı tek başına yeterli bir doğrulama değildir.\n## Karbon görünümlü kaplama ile karbon parça aynı mı?\nHayır. Karbon desenli film görsel bir kaplamadır; karbon lifli kompozitle aynı yapı değildir. Gerçek karbon kumaşının mevcut parça üzerine uygulanması da bağımsız bir kompozit parçayla aynı şey değildir. Ana parçanın korunduğu uygulamada toplam ağırlık azalacağı varsayılmamalıdır. Karbon/cam elyaf hibritlerde ise farklı takviyeler birlikte bulunur. Ürün açıklamasında yapının hangisi olduğu açıkça belirtilmelidir.\n## Satın almadan önce neye bakmalı?\nUyumluluk, malzeme bileşimi, bağlantı noktaları, yüzey ve montaj kapsamını birlikte incele. Ağırlık önemliyse karşılaştırılabilir koşullarda ölçülmüş ürün verisini iste. Doğrulanmamış genel yüzdeler yerine satın alacağın parçaya ait bilgiye dayan. Kullanım ve bakımda üreticinin ürün özelindeki talimatını izle; yüzey koruması, UV dayanımı veya ısı dayanımı bütün karbon parçalar için aynı kabul edilemez.\n### Karbon fiber her darbeye dayanır mı?\nHayır. Tasarımına ve darbenin biçimine göre hasar görebilir. Görünür yüzeyin sağlam olması iç yapıda hasar bulunmadığını tek başına kanıtlamaz. Şüpheli bir darbe sonrasında özellikle güvenlikle ilgili parçalarda uzman değerlendirmesi gerekir.\n### Parlak veya mat yüzey dayanımı belirler mi?\nParlak ve mat, yüzey tercihidir. Lif türü, katman düzeni ve üretim kalitesi hakkında tek başına kesin bir sonuç vermez.\n## Kendi parçan için nereden başlamalısın?\nAracının bilgilerini, parçanın farklı açılardan fotoğraflarını ve temel ölçülerini hazırlamak doğru bir başlangıçtır. Malzeme ve yöntem, görünüm hedefinin yanında parçanın görevine göre değerlendirilmelidir.", "ru": "Karbon fiber, çok ince karbon liflerinden oluşan bir takviye malzemesidir. Bir motosiklet veya otomobil parçasında gördüğümüz “karbon” çoğu zaman bu liflerin reçineyle bir araya geldiği kompozit yapıdır. Lifler yük taşımaya katkı sağlarken reçine lifleri bir arada tutar ve yükün aktarılmasına yardımcı olur.\n## Motosiklet ve araçlarda neden kullanılır?\nKarbon kompozitler, uygun tasarım ve üretimle düşük ağırlıkta yüksek rijitlik hedeflenen parçalarda tercih edilebilir. Grenaj, çamurluk ve kaplama parçalarında biçim verme esnekliği ile belirgin doku da seçim nedenidir. Ancak her karbon parça, değiştirdiği parçadan mutlaka daha hafif veya daha dayanıklı değildir. Kalınlık, reçine miktarı, katman düzeni ve bağlantı detayları sonucu değiştirir.\n## Lif yönü neden önemlidir?\nKompozit parçanın davranışı liflerin yönüne bağlıdır. Bir yönde iyi sonuç veren katman düzeni, başka yöndeki yük için aynı sonucu vermeyebilir. Bu yüzden görünür örgü deseni, parçanın bütün teknik yapısını açıklamaz. Özellikle taşıyıcı veya güvenlikle ilgili parçalarda malzeme adı tek başına yeterli bir doğrulama değildir.\n## Karbon görünümlü kaplama ile karbon parça aynı mı?\nHayır. Karbon desenli film görsel bir kaplamadır; karbon lifli kompozitle aynı yapı değildir. Gerçek karbon kumaşının mevcut parça üzerine uygulanması da bağımsız bir kompozit parçayla aynı şey değildir. Ana parçanın korunduğu uygulamada toplam ağırlık azalacağı varsayılmamalıdır. Karbon/cam elyaf hibritlerde ise farklı takviyeler birlikte bulunur. Ürün açıklamasında yapının hangisi olduğu açıkça belirtilmelidir.\n## Satın almadan önce neye bakmalı?\nUyumluluk, malzeme bileşimi, bağlantı noktaları, yüzey ve montaj kapsamını birlikte incele. Ağırlık önemliyse karşılaştırılabilir koşullarda ölçülmüş ürün verisini iste. Doğrulanmamış genel yüzdeler yerine satın alacağın parçaya ait bilgiye dayan. Kullanım ve bakımda üreticinin ürün özelindeki talimatını izle; yüzey koruması, UV dayanımı veya ısı dayanımı bütün karbon parçalar için aynı kabul edilemez.\n### Karbon fiber her darbeye dayanır mı?\nHayır. Tasarımına ve darbenin biçimine göre hasar görebilir. Görünür yüzeyin sağlam olması iç yapıda hasar bulunmadığını tek başına kanıtlamaz. Şüpheli bir darbe sonrasında özellikle güvenlikle ilgili parçalarda uzman değerlendirmesi gerekir.\n### Parlak veya mat yüzey dayanımı belirler mi?\nParlak ve mat, yüzey tercihidir. Lif türü, katman düzeni ve üretim kalitesi hakkında tek başına kesin bir sonuç vermez.\n## Kendi parçan için nereden başlamalısın?\nAracının bilgilerini, parçanın farklı açılardan fotoğraflarını ve temel ölçülerini hazırlamak doğru bir başlangıçtır. Malzeme ve yöntem, görünüm hedefinin yanında parçanın görevine göre değerlendirilmelidir."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.content (id,key,title,body) VALUES ('journal-processes','blog-infuzyon-laminasyon-nedir','{"tr": "İnfüzyon ve Laminasyon: Parçaya Giden Yol", "en": "İnfüzyon ve Laminasyon: Parçaya Giden Yol", "ru": "İnfüzyon ve Laminasyon: Parçaya Giden Yol"}'::jsonb,'{"tr": "Karbon bir parçanın görünümü kadar nasıl üretildiği de önemlidir. İnfüzyon ve laminasyon terimleri farklı işlemleri anlatırken aynı üretim zincirinin içinde de yer alabilir. Laminasyon genel olarak katmanlama işlemidir. KUZMIN’in talep formunda ise bu seçenek, mevcut parça üzerine gerçek karbon uygulamasını ifade eder.\n## Mevcut parça üzerine laminasyon nedir?\nBu uygulamada ana parça korunur; yüzeyi değerlendirilir ve karbon takviyesi uygun reçine sistemiyle üzerine uygulanır. Amaç, mevcut parçanın formunu karbon dokuyla buluşturmaktır. Ana parçanın malzemesi, yüzey durumu, geometrisi ve kullanım koşulları yöntemin uygunluğunu etkiler. Her plastik veya metal yüzeye aynı işlem uygulanabileceği varsayılmaz.\n## Laminasyon süreci nasıl ilerler?\nÖnce parçanın durumu ve beklenti değerlendirilir. Ardından yüzey hazırlığı, lifin yerleştirilmesi, reçine uygulaması ve uygun kürlenme koşulları planlanır. Kenar düzenleme ve yüzey işlemleri, malzeme sisteminin gerektirdiği aşamalardan sonra yapılır. Mevcut parça yerinde kaldığı için bu yöntem otomatik bir hafifletme işlemi değildir; ölçüler ve bağlantı toleransları da dikkate alınmalıdır.\n## Vakum infüzyon nedir?\nVakum infüzyonda kuru takviye malzemesi bir kalıp içine yerleştirilir ve sızdırmaz bir torbalama düzeni kurulur. Vakum farkı, uygun reçinenin lif yapısı boyunca ilerlemesini sağlar. Akışın tamamlanması ve reçinenin kürlenmesinden sonra parça kalıptan çıkarılır, kenarları düzenlenir ve gerekli kontroller yapılır. Kalıp, takviye ve reçine seçimi; parça geometrisi ve hedeflenen kullanıma bağlıdır.\n## İnfüzyonda hangi noktalar belirleyicidir?\nKalıp yüzeyi, liflerin yerleşimi, torbanın sızdırmazlığı, reçine akış planı ve kür koşulları birlikte değerlendirilir. “Vakumla üretildi” ifadesi tek başına belirli bir ağırlık, mekanik dayanım veya kalite belgesi anlamına gelmez. Sonuç, kullanılan sistem ve süreç kontrolüne bağlıdır.\n## Hangisini seçmelisin?\nMevcut parçanın üzerine karbon görünümü ve dokusu hedefleniyorsa kaplama yaklaşımı değerlendirilebilir. Bağımsız bir kompozit parça isteniyorsa kalıp ve üretim ihtiyacı ayrıca ele alınır. Her parça veya malzeme, her yönteme uygun olmayabilir. En doğru seçim fotoğraf, ölçü, bağlantı noktaları ve kullanım koşulları üzerinden yapılan değerlendirmeyle netleşir.\n### İnfüzyon her zaman tam karbon mudur?\nHayır. İnfüzyon bir üretim yöntemidir; karbon, cam elyaf veya farklı takviyelerle kullanılabilir. Malzeme bileşimi ayrıca açıklanmalıdır.\n### Bunlar evde uygulanabilecek basit işlemler mi?\nReçineler, kimyasallar ve kesim/toz işlemleri uygun ekipman, havalandırma ve koruma gerektirir. Bu yazı süreçlerin genel mantığını açıklar; ürün sistemine ait teknik ve güvenlik talimatlarının yerine geçmez.", "en": "Karbon bir parçanın görünümü kadar nasıl üretildiği de önemlidir. İnfüzyon ve laminasyon terimleri farklı işlemleri anlatırken aynı üretim zincirinin içinde de yer alabilir. Laminasyon genel olarak katmanlama işlemidir. KUZMIN’in talep formunda ise bu seçenek, mevcut parça üzerine gerçek karbon uygulamasını ifade eder.\n## Mevcut parça üzerine laminasyon nedir?\nBu uygulamada ana parça korunur; yüzeyi değerlendirilir ve karbon takviyesi uygun reçine sistemiyle üzerine uygulanır. Amaç, mevcut parçanın formunu karbon dokuyla buluşturmaktır. Ana parçanın malzemesi, yüzey durumu, geometrisi ve kullanım koşulları yöntemin uygunluğunu etkiler. Her plastik veya metal yüzeye aynı işlem uygulanabileceği varsayılmaz.\n## Laminasyon süreci nasıl ilerler?\nÖnce parçanın durumu ve beklenti değerlendirilir. Ardından yüzey hazırlığı, lifin yerleştirilmesi, reçine uygulaması ve uygun kürlenme koşulları planlanır. Kenar düzenleme ve yüzey işlemleri, malzeme sisteminin gerektirdiği aşamalardan sonra yapılır. Mevcut parça yerinde kaldığı için bu yöntem otomatik bir hafifletme işlemi değildir; ölçüler ve bağlantı toleransları da dikkate alınmalıdır.\n## Vakum infüzyon nedir?\nVakum infüzyonda kuru takviye malzemesi bir kalıp içine yerleştirilir ve sızdırmaz bir torbalama düzeni kurulur. Vakum farkı, uygun reçinenin lif yapısı boyunca ilerlemesini sağlar. Akışın tamamlanması ve reçinenin kürlenmesinden sonra parça kalıptan çıkarılır, kenarları düzenlenir ve gerekli kontroller yapılır. Kalıp, takviye ve reçine seçimi; parça geometrisi ve hedeflenen kullanıma bağlıdır.\n## İnfüzyonda hangi noktalar belirleyicidir?\nKalıp yüzeyi, liflerin yerleşimi, torbanın sızdırmazlığı, reçine akış planı ve kür koşulları birlikte değerlendirilir. “Vakumla üretildi” ifadesi tek başına belirli bir ağırlık, mekanik dayanım veya kalite belgesi anlamına gelmez. Sonuç, kullanılan sistem ve süreç kontrolüne bağlıdır.\n## Hangisini seçmelisin?\nMevcut parçanın üzerine karbon görünümü ve dokusu hedefleniyorsa kaplama yaklaşımı değerlendirilebilir. Bağımsız bir kompozit parça isteniyorsa kalıp ve üretim ihtiyacı ayrıca ele alınır. Her parça veya malzeme, her yönteme uygun olmayabilir. En doğru seçim fotoğraf, ölçü, bağlantı noktaları ve kullanım koşulları üzerinden yapılan değerlendirmeyle netleşir.\n### İnfüzyon her zaman tam karbon mudur?\nHayır. İnfüzyon bir üretim yöntemidir; karbon, cam elyaf veya farklı takviyelerle kullanılabilir. Malzeme bileşimi ayrıca açıklanmalıdır.\n### Bunlar evde uygulanabilecek basit işlemler mi?\nReçineler, kimyasallar ve kesim/toz işlemleri uygun ekipman, havalandırma ve koruma gerektirir. Bu yazı süreçlerin genel mantığını açıklar; ürün sistemine ait teknik ve güvenlik talimatlarının yerine geçmez.", "ru": "Karbon bir parçanın görünümü kadar nasıl üretildiği de önemlidir. İnfüzyon ve laminasyon terimleri farklı işlemleri anlatırken aynı üretim zincirinin içinde de yer alabilir. Laminasyon genel olarak katmanlama işlemidir. KUZMIN’in talep formunda ise bu seçenek, mevcut parça üzerine gerçek karbon uygulamasını ifade eder.\n## Mevcut parça üzerine laminasyon nedir?\nBu uygulamada ana parça korunur; yüzeyi değerlendirilir ve karbon takviyesi uygun reçine sistemiyle üzerine uygulanır. Amaç, mevcut parçanın formunu karbon dokuyla buluşturmaktır. Ana parçanın malzemesi, yüzey durumu, geometrisi ve kullanım koşulları yöntemin uygunluğunu etkiler. Her plastik veya metal yüzeye aynı işlem uygulanabileceği varsayılmaz.\n## Laminasyon süreci nasıl ilerler?\nÖnce parçanın durumu ve beklenti değerlendirilir. Ardından yüzey hazırlığı, lifin yerleştirilmesi, reçine uygulaması ve uygun kürlenme koşulları planlanır. Kenar düzenleme ve yüzey işlemleri, malzeme sisteminin gerektirdiği aşamalardan sonra yapılır. Mevcut parça yerinde kaldığı için bu yöntem otomatik bir hafifletme işlemi değildir; ölçüler ve bağlantı toleransları da dikkate alınmalıdır.\n## Vakum infüzyon nedir?\nVakum infüzyonda kuru takviye malzemesi bir kalıp içine yerleştirilir ve sızdırmaz bir torbalama düzeni kurulur. Vakum farkı, uygun reçinenin lif yapısı boyunca ilerlemesini sağlar. Akışın tamamlanması ve reçinenin kürlenmesinden sonra parça kalıptan çıkarılır, kenarları düzenlenir ve gerekli kontroller yapılır. Kalıp, takviye ve reçine seçimi; parça geometrisi ve hedeflenen kullanıma bağlıdır.\n## İnfüzyonda hangi noktalar belirleyicidir?\nKalıp yüzeyi, liflerin yerleşimi, torbanın sızdırmazlığı, reçine akış planı ve kür koşulları birlikte değerlendirilir. “Vakumla üretildi” ifadesi tek başına belirli bir ağırlık, mekanik dayanım veya kalite belgesi anlamına gelmez. Sonuç, kullanılan sistem ve süreç kontrolüne bağlıdır.\n## Hangisini seçmelisin?\nMevcut parçanın üzerine karbon görünümü ve dokusu hedefleniyorsa kaplama yaklaşımı değerlendirilebilir. Bağımsız bir kompozit parça isteniyorsa kalıp ve üretim ihtiyacı ayrıca ele alınır. Her parça veya malzeme, her yönteme uygun olmayabilir. En doğru seçim fotoğraf, ölçü, bağlantı noktaları ve kullanım koşulları üzerinden yapılan değerlendirmeyle netleşir.\n### İnfüzyon her zaman tam karbon mudur?\nHayır. İnfüzyon bir üretim yöntemidir; karbon, cam elyaf veya farklı takviyelerle kullanılabilir. Malzeme bileşimi ayrıca açıklanmalıdır.\n### Bunlar evde uygulanabilecek basit işlemler mi?\nReçineler, kimyasallar ve kesim/toz işlemleri uygun ekipman, havalandırma ve koruma gerektirir. Bu yazı süreçlerin genel mantığını açıklar; ürün sistemine ait teknik ve güvenlik talimatlarının yerine geçmez."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.content (id,key,title,body) VALUES ('journal-twill-forged','blog-twill-forged-karbon-farki','{"tr": "Twill mi, Forged mı? Karbon Dokusu Rehberi", "en": "Twill mi, Forged mı? Karbon Dokusu Rehberi", "ru": "Twill mi, Forged mı? Karbon Dokusu Rehberi"}'::jsonb,'{"tr": "Twill karbon ve Forged Carbon, aynı parçaya farklı görsel karakterler kazandırabilir. Seçim yaparken deseni, malzeme yapısını ve üretim yöntemini ayrı düşünmek gerekir. Görünür doku, parçanın bütün katmanlarını veya teknik performansını tek başına göstermez.\n## Twill karbonun düzenli çizgisi\nTwill, karbon kumaşında kullanılan bir örgü türüdür. Yaygın örneklerden biri 2×2 örgüdür; yüzeyde belirgin diyagonal çizgiler oluşturur. Bu düzenli görünüm, geniş yüzeylerde çizginin nasıl devam edeceğinin planlanmasını önemli hale getirir. Parçanın eğrileri ve kumaşın yerleşimi, görünen deseni etkileyebilir.\n## Forged Carbon’un farklı karakteri\nForged Carbon adı genellikle kesilmiş karbon liflerinin reçine içinde yer aldığı, daha düzensiz ve parçalı desenli kompozitleri anlatmak için kullanılır. Klasik bir kumaş örgüsü değildir. Görünüm parçadan parçaya değişebilir; fotoğraftaki damarların aynısının her üründe tekrarlanacağı beklenmemelidir. Kullanılan ticari ad, tek başına belirli bir üretim reçetesi veya sertifika anlamına gelmez.\n## Hangisi daha dayanıklı?\nYalnızca desene bakarak karar verilemez. Liflerin uzunluğu, yönlenmesi ve oranı; reçine, geometri ve üretim yöntemiyle birlikte sonucu belirler. Aynı nedenle “Forged her zaman daha güçlüdür” veya “Twill her zaman daha hafiftir” gibi genellemeler doğru bir ürün karşılaştırması değildir. Taşıyıcı bir görev için kullanım düşünülüyorsa parça özelinde doğrulanmış tasarım ve veri gerekir.\n## Parlak mı, mat mı?\nParlak yüzey ışığı daha belirgin yansıtarak dokunun derinlik algısını öne çıkarabilir. Mat yüzey daha yumuşak bir yansıma verir. Bunlar malzeme bileşimiyle aynı karar değildir: görünür desen, yüzey kaplaması ve parçanın yapısı ayrı ayrı sorulmalıdır. Bakım ve kimyasal dayanım için ilgili yüzey sisteminin talimatları esas alınır.\n## Birlikte kullanılan parçaları nasıl eşleştirmeli?\nAracın üzerinde yan yana gelecek parçalarda doku yönü, yüzey ve desenin görsel yoğunluğunu birlikte düşün. Tek bir yakın çekim yerine parçanın araç üzerindeki konumunu da gösteren fotoğraflar üzerinden karar ver. Kendi parçan için talep oluştururken istediğin dokuyu ve yüzeyi belirt; ölçü ve görseller üretim uygunluğunun değerlendirilmesine yardımcı olur.\n### Forged desen birebir aynı olur mu?\nKesilmiş liflerin dağılımı nedeniyle görsel farklılıklar oluşabilir. Tam olarak aynı desen önemliyse bu beklentiyi sipariş öncesinde açıkça paylaş.\n### Sadece görünüm seçmek yeterli mi?\nHayır. Motosiklet veya araç uyumluluğu, bağlantılar, malzeme bileşimi ve montaj kapsamı da netleşmelidir. Doku seçimi bu kararların görsel tarafıdır.", "en": "Twill karbon ve Forged Carbon, aynı parçaya farklı görsel karakterler kazandırabilir. Seçim yaparken deseni, malzeme yapısını ve üretim yöntemini ayrı düşünmek gerekir. Görünür doku, parçanın bütün katmanlarını veya teknik performansını tek başına göstermez.\n## Twill karbonun düzenli çizgisi\nTwill, karbon kumaşında kullanılan bir örgü türüdür. Yaygın örneklerden biri 2×2 örgüdür; yüzeyde belirgin diyagonal çizgiler oluşturur. Bu düzenli görünüm, geniş yüzeylerde çizginin nasıl devam edeceğinin planlanmasını önemli hale getirir. Parçanın eğrileri ve kumaşın yerleşimi, görünen deseni etkileyebilir.\n## Forged Carbon’un farklı karakteri\nForged Carbon adı genellikle kesilmiş karbon liflerinin reçine içinde yer aldığı, daha düzensiz ve parçalı desenli kompozitleri anlatmak için kullanılır. Klasik bir kumaş örgüsü değildir. Görünüm parçadan parçaya değişebilir; fotoğraftaki damarların aynısının her üründe tekrarlanacağı beklenmemelidir. Kullanılan ticari ad, tek başına belirli bir üretim reçetesi veya sertifika anlamına gelmez.\n## Hangisi daha dayanıklı?\nYalnızca desene bakarak karar verilemez. Liflerin uzunluğu, yönlenmesi ve oranı; reçine, geometri ve üretim yöntemiyle birlikte sonucu belirler. Aynı nedenle “Forged her zaman daha güçlüdür” veya “Twill her zaman daha hafiftir” gibi genellemeler doğru bir ürün karşılaştırması değildir. Taşıyıcı bir görev için kullanım düşünülüyorsa parça özelinde doğrulanmış tasarım ve veri gerekir.\n## Parlak mı, mat mı?\nParlak yüzey ışığı daha belirgin yansıtarak dokunun derinlik algısını öne çıkarabilir. Mat yüzey daha yumuşak bir yansıma verir. Bunlar malzeme bileşimiyle aynı karar değildir: görünür desen, yüzey kaplaması ve parçanın yapısı ayrı ayrı sorulmalıdır. Bakım ve kimyasal dayanım için ilgili yüzey sisteminin talimatları esas alınır.\n## Birlikte kullanılan parçaları nasıl eşleştirmeli?\nAracın üzerinde yan yana gelecek parçalarda doku yönü, yüzey ve desenin görsel yoğunluğunu birlikte düşün. Tek bir yakın çekim yerine parçanın araç üzerindeki konumunu da gösteren fotoğraflar üzerinden karar ver. Kendi parçan için talep oluştururken istediğin dokuyu ve yüzeyi belirt; ölçü ve görseller üretim uygunluğunun değerlendirilmesine yardımcı olur.\n### Forged desen birebir aynı olur mu?\nKesilmiş liflerin dağılımı nedeniyle görsel farklılıklar oluşabilir. Tam olarak aynı desen önemliyse bu beklentiyi sipariş öncesinde açıkça paylaş.\n### Sadece görünüm seçmek yeterli mi?\nHayır. Motosiklet veya araç uyumluluğu, bağlantılar, malzeme bileşimi ve montaj kapsamı da netleşmelidir. Doku seçimi bu kararların görsel tarafıdır.", "ru": "Twill karbon ve Forged Carbon, aynı parçaya farklı görsel karakterler kazandırabilir. Seçim yaparken deseni, malzeme yapısını ve üretim yöntemini ayrı düşünmek gerekir. Görünür doku, parçanın bütün katmanlarını veya teknik performansını tek başına göstermez.\n## Twill karbonun düzenli çizgisi\nTwill, karbon kumaşında kullanılan bir örgü türüdür. Yaygın örneklerden biri 2×2 örgüdür; yüzeyde belirgin diyagonal çizgiler oluşturur. Bu düzenli görünüm, geniş yüzeylerde çizginin nasıl devam edeceğinin planlanmasını önemli hale getirir. Parçanın eğrileri ve kumaşın yerleşimi, görünen deseni etkileyebilir.\n## Forged Carbon’un farklı karakteri\nForged Carbon adı genellikle kesilmiş karbon liflerinin reçine içinde yer aldığı, daha düzensiz ve parçalı desenli kompozitleri anlatmak için kullanılır. Klasik bir kumaş örgüsü değildir. Görünüm parçadan parçaya değişebilir; fotoğraftaki damarların aynısının her üründe tekrarlanacağı beklenmemelidir. Kullanılan ticari ad, tek başına belirli bir üretim reçetesi veya sertifika anlamına gelmez.\n## Hangisi daha dayanıklı?\nYalnızca desene bakarak karar verilemez. Liflerin uzunluğu, yönlenmesi ve oranı; reçine, geometri ve üretim yöntemiyle birlikte sonucu belirler. Aynı nedenle “Forged her zaman daha güçlüdür” veya “Twill her zaman daha hafiftir” gibi genellemeler doğru bir ürün karşılaştırması değildir. Taşıyıcı bir görev için kullanım düşünülüyorsa parça özelinde doğrulanmış tasarım ve veri gerekir.\n## Parlak mı, mat mı?\nParlak yüzey ışığı daha belirgin yansıtarak dokunun derinlik algısını öne çıkarabilir. Mat yüzey daha yumuşak bir yansıma verir. Bunlar malzeme bileşimiyle aynı karar değildir: görünür desen, yüzey kaplaması ve parçanın yapısı ayrı ayrı sorulmalıdır. Bakım ve kimyasal dayanım için ilgili yüzey sisteminin talimatları esas alınır.\n## Birlikte kullanılan parçaları nasıl eşleştirmeli?\nAracın üzerinde yan yana gelecek parçalarda doku yönü, yüzey ve desenin görsel yoğunluğunu birlikte düşün. Tek bir yakın çekim yerine parçanın araç üzerindeki konumunu da gösteren fotoğraflar üzerinden karar ver. Kendi parçan için talep oluştururken istediğin dokuyu ve yüzeyi belirt; ölçü ve görseller üretim uygunluğunun değerlendirilmesine yardımcı olur.\n### Forged desen birebir aynı olur mu?\nKesilmiş liflerin dağılımı nedeniyle görsel farklılıklar oluşabilir. Tam olarak aynı desen önemliyse bu beklentiyi sipariş öncesinde açıkça paylaş.\n### Sadece görünüm seçmek yeterli mi?\nHayır. Motosiklet veya araç uyumluluğu, bağlantılar, malzeme bileşimi ve montaj kapsamı da netleşmelidir. Doku seçimi bu kararların görsel tarafıdır."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.content(id,key,title,body)
SELECT 'home-bestsellers','home-bestsellers','{"tr":"Ana sayfa · En çok satanlar","en":"Homepage · Bestsellers","ru":"Главная · Популярные товары"}'::jsonb,
jsonb_build_object('tr',jsonb_build_object('productIds',coalesce((SELECT jsonb_agg(id) FROM (SELECT id FROM public.products WHERE published ORDER BY id LIMIT 3) p),'[]'::jsonb),'intervalSeconds',5,'frames','{}'::jsonb)::text,'en','','ru','') ON CONFLICT DO NOTHING;
UPDATE public.site_workspace w SET catalog=jsonb_set(w.catalog,'{content}',
 (SELECT coalesce(jsonb_agg(entry),'[]'::jsonb) FROM (
  SELECT CASE WHEN p->>'key'='about' THEN p||jsonb_build_object('body',coalesce(p->'body','{}'::jsonb)||'{"tr": "Bir motosikleti veya aracı kişisel kılan şey, detaylara gösterilen özen. KUZMIN’de karbonun dokusunu, parçanın çizgisini ve kullanım amacını birlikte düşünürüz.\nHazır bir parça ararken de aklındaki fikri geliştirirken de başlangıç noktamız aynı: aracı, parçayı ve beklentini anlamak. Malzeme, yüzey, ölçü ve uyumluluk bilgilerini açıkça paylaşarak karar vermeni kolaylaştırmayı amaçlarız.\nAradığın parçayı bulamadığında birkaç fotoğraf, temel ölçüler ve kısa bir açıklamayla talep oluşturabilirsin. Parçanın yapısı ve istediğin sonuç üzerinden üretim veya uygulama yöntemi değerlendirilir; kapsam ve teklif birlikte netleşir.\nSade bir görünüm, doğru uyumluluk ve açık iletişim. KUZMIN’in yaklaşımı, senin parçanı ve beklentini merkeze alır."}'::jsonb)
   WHEN p->>'key'='privacy' THEN jsonb_set(p,'{body,tr}',to_jsonb(replace(replace(p->'body'->>'tr','Çerez tercih kaydı bu tarayıcıda 180 gün tutulur; süresi dolduğunda yeniden seçim istenir.','Çerez bildirimi siteye her yeni girişte ve sayfa yenilendiğinde yeniden açılır. Önceki kabul bu ziyaret için otomatik izin sayılmaz; gerekli olmayan analiz yeni seçim yapılana kadar kapalıdır. Son tercih kaydı senkronizasyon amacıyla bu tarayıcıda en fazla 180 gün tutulabilir.'),'İsteğe bağlı analiz ilk ziyarette kapalıdır.','İsteğe bağlı analiz her yeni ziyarette başlangıçta kapalıdır.'))) ELSE p END AS entry
  FROM jsonb_array_elements(coalesce(w.catalog->'content','[]'::jsonb)) p
  UNION ALL
  SELECT to_jsonb(c) FROM public.content c WHERE c.key IN ('home-bestsellers','blog-karbon-fiber-nedir','blog-infuzyon-laminasyon-nedir','blog-twill-forged-karbon-farki')
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(w.catalog->'content','[]'::jsonb)) p WHERE p->>'key'=c.key)
 ) records)), revision=revision+1 WHERE w.id='site';
COMMIT;
